const MIN_PORT = 1;
const MAX_PORT = 65535;

/** Context for {@link resolveDevCommandOptions}. */
export interface ResolveDevCommandOptions {
  /** The environment variables to read overrides from (e.g. `process.env`). Defaults to `{}`. */
  env?: AgentEnvironment;
}

/**
 * Map of CLI option keys to the environment variable that overrides them. A truthy env value always
 * takes precedence over the CLI-provided value.
 */
const ENV_OVERRIDES: ReadonlyArray<readonly [optionKey: string, envName: string]> = [
  ['ci', 'CI'],
  ['configDir', 'SBCONFIG_CONFIG_DIR'],
  ['host', 'SBCONFIG_HOSTNAME'],
  ['staticDir', 'SBCONFIG_STATIC_DIR'],
];

/**
 * Parse and validate a port value coming from either the CLI (usually a number) or an environment
 * variable (always a string). Placeholder strings such as `$PORT` are treated as invalid rather
 * than interpolated, and empty or whitespace-only strings are rejected.
 *
 * @throws If the value is not an integer between {@link MIN_PORT} and {@link MAX_PORT}.
 */
function parsePort(value: string | number): number {
  const isString = typeof value === 'string';
  const formatted = isString ? `"${value}"` : `${value}`;

  const fail = (): never => {
    throw new Error(
      `Invalid value at port. Port must be a valid number from 1 to 65535, received ${formatted}.`
    );
  };

  let numeric: number;
  if (isString) {
    const trimmed = value.trim();
    // Reject empty/whitespace-only strings and anything that isn't a plain integer (e.g. "$PORT").
    if (trimmed === '' || !/^\d+$/.test(trimmed)) {
      return fail();
    }
    numeric = Number(trimmed);
  } else {
    numeric = value;
  }

  if (!Number.isInteger(numeric) || numeric < MIN_PORT || numeric > MAX_PORT) {
    return fail();
  }

  return numeric;
}

/** Returns the first candidate that has actually been provided (i.e. is not `undefined`/`null`). */
function firstProvided(candidates: Array<string | number | undefined | null>) {
  return candidates.find((candidate) => candidate !== undefined && candidate !== null);
}

/**
 * Resolve the effective options for the `dev` command by layering environment variable overrides on
 * top of the CLI-provided options and adjusting behavior for AI coding assistants.
 *
 * - Truthy `CI`, `SBCONFIG_CONFIG_DIR`, `SBCONFIG_HOSTNAME`, and `SBCONFIG_STATIC_DIR` env values
 *   override their respective CLI options.
 * - Port precedence is `--port` > `SBCONFIG_PORT` > `PORT` normally, but `PORT` > `--port` >
 *   `SBCONFIG_PORT` when launched by Claude's preview launcher (which assigns the port itself).
 * - The browser is never auto-opened during a Claude preview launch; otherwise `open` is preserved.
 * - All unrelated CLI options are passed through untouched.
 */
export function resolveDevCommandOptions<T extends Record<string, any>>(
  cliOptions: T,
  options: ResolveDevCommandOptions = {}
): T {
  const env = options.env ?? {};
  const resolved: Record<string, any> = { ...cliOptions };

  // Apply truthy env overrides; env wins over CLI-provided values.
  for (const [optionKey, envName] of ENV_OVERRIDES) {
    const value = env[envName];
    if (value) {
      resolved[optionKey] = value;
    }
  }

  const claudePreview = isClaudePreviewLaunch(env);

  // Port precedence depends on how Storybook was launched.
  const portCandidate = firstProvided(
    claudePreview
      ? [env.PORT, cliOptions.port, env.SBCONFIG_PORT]
      : [cliOptions.port, env.SBCONFIG_PORT, env.PORT]
  );

  if (portCandidate !== undefined && portCandidate !== null) {
    resolved.port = parsePort(portCandidate);
  }

  // Claude's preview launcher manages the browser itself, so never auto-open.
  if (claudePreview) {
    resolved.open = false;
  }

  return resolved as T;
}
